solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <set>
#include <vector>

enum class Op { Plain, Call, Jump, Branch, Return };
struct Insn { std::uint32_t address; std::uint32_t length; Op op; std::uint32_t target; };
struct Block { std::uint32_t start; std::uint32_t end; std::vector<std::uint32_t> successors; };

std::vector<Block> basicBlocks(const std::vector<Insn>& code)
{
    if (code.empty()) return {};
    std::set<std::uint32_t> addresses;
    for (const Insn& i : code) addresses.insert(i.address);
    std::set<std::uint32_t> leaders{ code.front().address };
    for (std::size_t k{ 0 }; k < code.size(); ++k)
    {
        const Insn& i{ code[k] };
        if ((i.op == Op::Jump || i.op == Op::Branch) && addresses.count(i.target)) leaders.insert(i.target);
        if ((i.op == Op::Jump || i.op == Op::Branch || i.op == Op::Return) && k + 1 < code.size()) leaders.insert(code[k + 1].address);
    }
    std::vector<Block> blocks;
    for (std::size_t k{ 0 }; k < code.size(); ++k)
    {
        if (leaders.count(code[k].address)) blocks.push_back({ code[k].address, 0, {} });
        const Insn& i{ code[k] };
        Block& b{ blocks.back() };
        b.end = i.address + i.length;
        const bool last{ k + 1 == code.size() || leaders.count(code[k + 1].address) > 0 };
        if (!last) continue;
        std::set<std::uint32_t> next;
        const bool fallsThrough{ i.op != Op::Jump && i.op != Op::Return && k + 1 < code.size() };
        if (fallsThrough) next.insert(code[k + 1].address);
        if ((i.op == Op::Jump || i.op == Op::Branch) && addresses.count(i.target)) next.insert(i.target);
        b.successors.assign(next.begin(), next.end());
    }
    return blocks;
}

unitTests:
using U = std::vector<std::uint32_t>;
// int sum(int* v, int n) { int t = 0; for (int i = 0; i < n; ++i) t += v[i]; return t; } in the shape of lesson 2.03
static std::vector<Insn> loop()
{
    return {
        { 0x00, 2, Op::Plain, 0 },       // xor eax, eax
        { 0x02, 2, Op::Plain, 0 },       // test edx, edx
        { 0x04, 2, Op::Branch, 0x14 },   // jle done
        { 0x06, 3, Op::Plain, 0 },       // xor r8d, r8d
        { 0x09, 4, Op::Plain, 0 },       // top: add eax, [rcx+r8*4]
        { 0x0D, 3, Op::Plain, 0 },       // inc r8
        { 0x10, 2, Op::Plain, 0 },       // cmp r8, rdx
        { 0x12, 2, Op::Branch, 0x09 },   // jl top
        { 0x14, 1, Op::Return, 0 },      // done: ret
    };
}

TEST("blocks of a loop") {
    const auto b{ basicBlocks(loop()) };
    CHECK_EQ(b.size(), 4u);
    if (b.size() != 4) return;
    CHECK_EQ(b[0].start, 0x00u); CHECK_EQ(b[0].end, 0x06u); CHECK_EQ(b[0].successors, (U{ 0x06, 0x14 }));
    CHECK_EQ(b[1].start, 0x06u); CHECK_EQ(b[1].end, 0x09u); CHECK_EQ(b[1].successors, (U{ 0x09 }));
    CHECK_EQ(b[2].start, 0x09u); CHECK_EQ(b[2].end, 0x14u); CHECK_EQ(b[2].successors, (U{ 0x09, 0x14 }));
    CHECK_EQ(b[3].start, 0x14u); CHECK(b[3].successors.empty());
}
TEST("calls do not split blocks; jumps and returns do") {
    const std::vector<Insn> code{
        { 0x10, 5, Op::Call, 0x900 },
        { 0x15, 2, Op::Jump, 0x1A },
        { 0x17, 1, Op::Return, 0 },
        { 0x18, 2, Op::Plain, 0 },
        { 0x1A, 1, Op::Return, 0 },
    };
    const auto b{ basicBlocks(code) };
    CHECK_EQ(b.size(), 4u);
    if (b.size() != 4) return;
    CHECK_EQ(b[0].start, 0x10u); CHECK_EQ(b[0].end, 0x17u); CHECK_EQ(b[0].successors, (U{ 0x1A }));
    CHECK_EQ(b[1].start, 0x17u); CHECK(b[1].successors.empty());
    CHECK_EQ(b[2].start, 0x18u); CHECK_EQ(b[2].successors, (U{ 0x1A }));
}
TEST("tail calls and branches to the next instruction") {
    const std::vector<Insn> code{
        { 0x0, 2, Op::Branch, 0x2 },
        { 0x2, 5, Op::Jump, 0x5000 },
    };
    const auto b{ basicBlocks(code) };
    CHECK_EQ(b.size(), 2u);
    if (b.size() != 2) return;
    CHECK_EQ(b[0].successors, (U{ 0x2 }));
    CHECK(b[1].successors.empty());
    CHECK(basicBlocks({}).empty());
}

